def add(prefix,title,en,ds,es,td,te,sd,se,rd,re,coresde,coresen):
 g=contracts[prefix]['wholeGoal']; assert all(len(x)==6 for x in [td,te,sd,se,rd,re]);phase=g['dimensionTags']['phase'];mid=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://skillpilot.com/economics/20261010/policy7/'+g['id']));capde='Bewertet wird die ganze Arbeit. Fehlt eine der folgenden eigenständig nötigen Leistungen vollständig oder ist sie durchgehend sachlich falsch, beträgt die Gesamtbewertung höchstens 14 von 24 BE: '+coresde+'. Nachvollziehbare, auch unvollständige richtige Teilleistungen an beliebiger Stelle zählen; ein Einzel- oder Rechenfehler, eine ausgelassene Zeile, ein abweichendes begründetes Urteil oder fehlende Fachlabels lösen diese Grenze nicht aus. Keine Aufgabe verlangt ein politisch vorgegebenes Ergebnis. Punkte sind nach den sechs konkreten Rastern anteilig zu vergeben; die Grenze ersetzt keine Einzelfallbewertung.';capen='Assess the entire submission. If any of the following independently necessary performances is wholly absent or consistently substantively wrong, the total is at most 14 of 24 points: '+coresen+'. Recognisable correct partial performance anywhere in the submission counts. One isolated error, a missing row, a reasoned alternative judgment or missing specialist labels does not trigger the limit. No politically prescribed conclusion is required. Award partial credit under the six concrete rubrics; the limit does not replace individual grading.'
 taskde='**Zwei unterschiedliche Fallvarianten — 24 BE, Bestehensgrenze 15.** Beide Varianten sind zu bearbeiten. Je Aufgabe 4 BE. Alle ausdrücklich als Modell bezeichneten Bedingungen sind eigene erfundene Unterrichtsdaten.\n\n'+ds+'\n\n'+'\n\n'.join(f'{i+1}. {t} **4 BE**' for i,t in enumerate(td))+'\n\n'+capde
 tasken='**Two different case variants — 24 points, passing threshold 15.** Address both variants. Each task is worth 4 points. All expressly labelled model conditions are original invented classroom data.\n\n'+es+'\n\n'+'\n\n'.join(f'{i+1}. {t} **4 points**' for i,t in enumerate(te))+'\n\n'+capen
 solde='\n\n'.join(f'{i+1}. {t}\nRaster: {rd[i]}' for i,t in enumerate(sd))+'\n\n'+capde
 solen='\n\n'.join(f'{i+1}. {t}\nRubric: {re[i]}' for i,t in enumerate(se))+'\n\n'+capen
 z={'id':mid,'title':phase+': '+title,'titleEn':phase+': '+en,'description':'Die lernende Person kann zwei unterschiedliche gegebene Fälle zu '+g['title']+' selbstständig fachlich bearbeiten, begründen und kritisch beurteilen.','descriptionEn':'The learner can independently analyse, justify and critically assess two different supplied cases on '+g['titleEn']+'.','weight':1,'tags':[t for t in g['tags'] if t in ['GK','LK']]+['Practice','Assessment'],'contains':[],'requires':[g['id']],'type':'atomic','phase':phase,'dimensionTags':{'framework':'canonical-gymnasium-economics','demandLevel':'AB3','phase':phase},'extendedData':{'applicabilityFromRequires':True},'examData':{'reviewStatus':'draft','coveredGoalIds':[g['id']],'coveredStrands':[g['title']],'demandLevels':['AB1','AB2','AB3'],'taskContent':taskde,'taskContentEn':tasken,'solutionContent':solde,'solutionContentEn':solen,'scoring':{'maxPoints':24,'passingPoints':15,'steps':[{'id':'s'+str(i+1),'points':4,'description':rd[i]+' / '+re[i]} for i in range(6)]}}};items.append(z)
add('4552c393','Leitbilder an historischem Einbruch und aktuellem Angebotsdruck','Principles under historical contraction and current supply pressures',
'''**A — Historischer Anker und eigene rückblickende Empfehlungen.** [DHM/LeMO, Weltwirtschaftskrise](https://www.dhm.de/lemo/kapitel/weimarer-republik/industrie-und-wirtschaft/weltwirtschaftskrise), Seitenstand 02.12.2022, gelesen 10.10.2026: Deutschlands Warenexport fiel 1929–1932 von 13,5 auf 5,7 Mrd. Reichsmark; Produktion sank um etwa 40%, Auslandskredite wurden abgezogen. Das ist eine spätere Museumsdarstellung über einen historischen Verlauf. Eigenes ergänzendes Krisenmodell: freie Werkstattkapazitäten, sinkende Bestellungen und vorsichtige Banken; ein verfügbarer öffentlicher Budgetbetrag 10 verdrängt andere Ausgaben. Zwei frei erfundene, rückblickende Theorie-Karten: K hält Nachfrageausfälle bei freien Kapazitäten für ein Problem und befürwortet befristete Aufträge mit offengelegter Finanzierung; O betont verlässliche Wettbewerbsregeln, freien Marktzugang und durchsetzende Institutionen statt willkürlicher Firmenbegünstigung. Diese Karten sind keine damaligen Politikerzitate; insbesondere wird keine damalige Umsetzung einer später formulierten Theorie behauptet. Vorschläge: sechs Einheiten allgemeine Kaufunterstützung und vier Einheiten Verwaltung; alternativ sechs für wettbewerblich vergebene Reparaturaufträge und vier für Abwicklung. Kein Multiplikator oder garantierter Erfolg ist gegeben.

**B — Datiertes aktuelles Material, eigene Entscheidungslage.** [EZB-Beschluss 10.09.2026](https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.mp260910~314e508016.en.html), gelesen 10.10.2026: +25 Basispunkte bei Inflationsdruck und unsicheren Aussichten. Eigene fiktive Region am 10.10.2026: Energieangebot knapp, wenig freie Baukapazität; einkommensarme Haushalte reduzieren Konsum. Budget 10: Option X verteilt 10 ohne Zielgruppenprüfung; Option Y verwendet 4 für gezielte Entlastung und 6 für später verfügbare Energieeffizienz mit offenem Anbieterwettbewerb. Nebenbedingung: sechs Einheiten Effizienzprojekt können erst im zweiten Jahr wirken. K und O gelten als vorgelegte Begründungsrahmen, nicht als Parteizuschreibungen. Zentralbankbeschluss und staatliche Budgetwahl gehören unterschiedlichen Institutionen an.''',
'''**A — Historical anchor and original retrospective recommendations.** [DHM/LeMO, Great Depression](https://www.dhm.de/lemo/kapitel/weimarer-republik/industrie-und-wirtschaft/weltwirtschaftskrise), page dated 2 December 2022, read 10 October 2026: German goods exports fell from RM13.5bn to RM5.7bn in 1929–1932; production fell about 40% and foreign credit was withdrawn. This is a later museum account. Added original crisis model: spare workshop capacity, falling orders and cautious banks; public budget10 displaces other expenditure. Two invented retrospective theory cards: K treats a demand shortfall under idle capacity as a problem and supports temporary financed orders; O stresses reliable competition rules, open entry and enforcing institutions instead of arbitrary firm favouritism. These are not contemporary quotations or claims that later theories were implemented then. Options:6general purchasing support plus4administration, or6competitively awarded repair orders plus4administration. No multiplier or guaranteed success is given.

**B — Dated current material and an original decision.** [ECB decision, 10 September 2026](https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.mp260910~314e508016.en.html), read 10 October 2026: +25basis points under inflation pressure and uncertainty. Fictional region dated10October2026: energy supply tight, little spare construction capacity; low-income households cut spending. Budget10: X distributes10without targeting; Y spends4on targeted relief and6on competitively procured energy efficiency available only from year2. K and O are supplied reasoning frameworks, not party labels. Monetary decisions and government budgets concern distinct institutions.''',
['Für A: Berechne den Exportrückgang in Prozent. Verbinde Kredit-/Nachfragebefund mit einer materialgebundenen Diagnose und kennzeichne, was das ergänzende Kapazitätsmodell hinzufügt.','Wende K und O jeweils konkret auf A an. Begründe eine Empfehlung und ihren Wirkungsweg unter dem Budget; zeige eine mögliche Ergänzung statt eines bloßen Theorieetiketts.','Prüfe die Aussage: „Die historische Zahl beweist, dass genau unsere Aufträge die Krise beendet hätten.“ Nenne einen überprüfbaren Annahmetest und eine Quellen-/Kausalgrenze.','Für B: Trenne den tatsächlichen datierten Beschluss von den eigenen Regionaldaten und ordne X/Y unter K und O begründet ein.','Vergleiche erwartete Nachfrage-, Wettbewerbs- und Angebotswirkungen von X/Y mit Zeit und Finanzierung. Begründe eine Wahl oder eine budgetfähige andere Mischung.','Vergleiche A und B: Warum sind identische Ausgaben keine identische Empfehlung? Entwickle eine Revisionsregel und trenne vorgeschlagene Wirkung, beobachteten Verlauf und offene Daten.'],
['For A, calculate the percentage export decline. Connect credit/demand evidence to a dossier-grounded diagnosis and identify the added capacity assumptions.','Apply K and O separately to A. Justify a budget-feasible recommendation and mechanism, showing possible complementarity rather than labels.','Assess: “The historical number proves our orders would have ended the crisis.” Give a testable assumption and a source/causal limit.','For B, separate the actual dated decision from invented regional data and classify X/Y under K and O with reasons.','Compare demand, competition and supply effects of X/Y, including timing and funding. Justify a choice or another feasible mixture.','Compare A/B: why is equal spending not the same recommendation? Develop an adaptation signal and separate proposed effects, observed events and missing evidence.'],
['(13,5−5,7)/13,5≈57,78%. Kreditausfall kann Investitionen/Bestellungen dämpfen; der Handels- und Produktionseinbruch passt dazu, beweist aber keine einzige Ursache. Freie Werkstattkapazität ist eine Unterrichtsannahme, keine aus dieser Zahl gemessene Auslastungsquote.','K: Aufträge können bei verfügbaren Arbeitskräften/Kapazitäten Ausgaben und Beschäftigung stützen; Finanzierung/Verdrängung kann begrenzen. O: offene Vergabe und klare Regeln vermindern Begünstigung und schützen Wettbewerb, erzeugen aber nicht automatisch sofort Nachfrage. Wettbewerbliche Aufträge6+Abwicklung4 verbinden beide, ohne sichere Wirkung.','Die Museumsdaten sind historischer Verlauf, die Empfehlung ist kontrafaktisch. Ohne Vergleich und Umsetzung kann weder kausaler Erfolg noch die Ausschließlichkeit eines Leitbilds behauptet werden. Auftragsbestand, freie geeignete Arbeitskräfte und tatsächliche zusätzliche Bestellungen prüfen; Kredit-/Handelskrise mitbedenken.','EZB+25Basispunkte ist ein dokumentierter Beschluss; die regionale Knappheit und10Budget sind fiktiv. X lässt sich als Nachfrageimpuls diskutieren, K verlangt aber Kapazitätsprüfung. Y kombiniert gezielte Nachfrage mit späterem Angebot; offener Anbieterwettbewerb passt O. Staatlicher Eingriff allein bestimmt keine Schule.','X kann Nachfrage gerade bei Engpass preiswirksam erhöhen; Y lindert gezielt Belastung4 und investiert6, Wirkung erst abJahr2. Entlastung setzt Zugang voraus, Effizienz Kapazität/Umsetzung; dieselben10 fehlen anderen Zwecken. Y ist vertretbar, aber auch begründete begrenzte Alternativen zählen.','A nimmt freie Kapazität und Nachfrageschwäche an, B Energie-/Bauengpässe: Maßnahmen können anders auf Mengen/Preise wirken. Fortschritt und tatsächliche Energieeinsparung/Preisdruck prüfen, bei Verzögerung umplanen. Keine gesamte historische Kausalität oder heutige Erfolgsgarantie ableiten.'],
['(13.5−5.7)/13.5≈57.78%. Credit contraction can weaken investment/orders; the output/trade decline fits this without proving one cause. Spare capacity is a classroom assumption, not a measured utilisation ratio.','K: financed orders may support spending/jobs if suitable resources are idle, with displacement limits. O: open procurement and stable rules protect competition without instantly generating demand.6orders+4administration can combine both without guaranteed effects.','Museum figures describe events; the recommendation is counterfactual. Without comparison/implementation neither success nor one exclusively correct framework follows. Check order books, suitable idle resources and genuinely additional orders; retain credit/trade causes.','The ECB move is documented; regional shortage/budget10 are invented. X can stimulate demand but K requires capacity checks. Y combines targeted demand and later supply; open competition fits O. State intervention alone does not identify a school.','X may add price pressure under shortages. Y relieves4and invests6, with supply benefits only fromyear2. Access, capacity and delivery matter; the10displaces alternatives. Y or another explicitly feasible conditional mix may be justified.','A assumes idle capacity/weak demand; B energy/construction constraints. Quantity/price effects differ. Monitor delivery and actual savings/price pressure, revise after delays; neither historical causality nor future success is guaranteed.'],
['2 BE für Prozentrechnung und begrenzten historischen Befund; 2 für Kredit-/Nachfragekette und klare Modellannahme.','2 BE für konkrete K-Anwendung mit Mechanismus; 2 für konkrete O-Anwendung und begründete budgetfähige Ergänzung.','2 BE für historische Evidenz/kontrafaktische Empfehlung getrennt; 2 für überprüfbare Voraussetzung und kausale Grenze.','2 BE für realen Beschluss/fiktive Lage getrennt; 2 für konkrete begründete K/O-Zuordnung.','2 BE für unterschiedliche Mengen-/Preis-/Wettbewerbsmechanismen; 2 für Finanzierung, Zeit und bedingte Wahl.','2 BE für entscheidenden A/B-Bedingungsunterschied; 2 für tatsächliches Prüfsignal und ehrliche Wirkungsgrenze.'],
['2points for decline and bounded historical evidence;2for credit/demand mechanism and model assumption.','2for specific K reasoning;2for O reasoning and feasible complementarity.','2for separating evidence/counterfactual;2for testable condition and causal limit.','2for decision/model separation;2for reasoned K/O classification.','2for quantity/price/competition mechanisms;2for funding/time/conditional choice.','2for decisive A/B difference;2for a checkable signal and evidence limit.'],
'eine fallgebundene Diagnose; konkrete Anwendung jedes der beiden vorgelegten Leitbilder mit Wirkungsweg; eine bedingte finanzierbare Empfehlung; die Unterscheidung tatsächlicher Quellenbefunde von erfundenen Annahmen und unbewiesener kausaler Wirkung',
'a case-grounded diagnosis; concrete application and mechanism for each supplied framework; a conditional financed recommendation; separation of actual source evidence, invented assumptions and unproved causality')
add('72484041','Wettbewerbsregeln, Aufträge und doppelte Investitionswirkung','Competition rules, orders and dual investment effects',
'''Alle Fälle sind fiktiv. Vorgelegte Begründungen: L betont dezentrale Entscheidungen, verlässliche allgemeine Regeln und Zurückhaltung bei dauernder Einzelbegünstigung. O verlangt einen staatlich durchsetzbaren Rahmen gegen Kartelle und Zugangssperren. K befürwortet bei Nachfragemangel/freien Kapazitäten einen befristeten Nachfrageimpuls, nicht jede beliebige Staatsausgabe. Diese Kurzmodelle sind keine vollständigen Aussagen aller Varianten einer Denkschule.
**A:** Zwei Anbieter teilen Gebiete auf; neue Unternehmen dürfen wegen einer sachlich unbegründeten Eintrittssperre nicht teilnehmen. Dauerhafte Regel R beseitigt Kartellabsprachen und Eintrittssperre, mit unabhängiger Aufsicht. Getrennt besteht Nachfragerückgang bei freien Reparaturkapazitäten. Programm S vergibt für ein Jahr zusätzlich Reparaturaufträge10 aus umgeschichtetem Budget; es verdrängt andere Ausgaben10, endet danach und wird offen ausgeschrieben.
**B:** Region plant Netzanbindung20 aus einem bereits begrenzten Budget20. Bauaufträge wirken im ersten Jahr, falls Arbeiter/Material frei sind; abJahr3 können Transportkosten sinken und neue Anbieter Kunden erreichen. Es bestehen zwei Begründungen: K hebt Auslastung während Auftragsmangel hervor, L/O verlässliche allgemeine Zugangsbedingungen statt Subvention nur eines Stammkunden. Wenn Baukapazitäten ausgelastet sind, ist zusätzliche Menge nicht gesichert. Keine Wirkungsgröße ist empirisch gemessen.''',
'''All cases are invented. Supplied frames: L favours decentralised decisions, predictable general rules and restraint over persistent selective subsidies. O requires enforceable competition rules against cartels/entry barriers. K favours temporary demand support under weak demand/spare capacity, not arbitrary public expenditure. These simplified cards do not represent every variant of each school.
**A:** Two suppliers divide territories; an unjustified entry barrier blocks newcomers. Lasting rule R removes cartels/barriers with independent enforcement. Separately demand falls with idle repair capacity. One-year S openly procures additional repairs10from a reallocated budget, displacing10other spending and then ending.
**B:** Network project20uses a limited budget20. Construction demand occurs inyear1if resources are idle; fromyear3transport costs may fall and entrants reach customers. K stresses temporary utilisation; L/O emphasise reliable general access rather than favouring one incumbent. If construction is fully utilised, extra output is not assured. No effect estimate is measured.''',
['Ordne R und S nach Ordnungs-/Prozessbezug ein und erkläre die entscheidenden Wirkungswege. Warum reicht die Dauer allein nicht?','Verbinde R/S begründet mit L, O und K; behandle staatliche Durchsetzung und begrenzte Nachfragewirkung konkret.','Beurteile eine Kombination R+S und die Behauptung „Alles Staatliche ist K“. Nenne Finanzierung und eine Bedingung, die eine Zuordnung oder Empfehlung begrenzt.','Für B: Trenne kurzfristigen Baunachfrage- und langfristigen Zugangs-/Produktivitätskanal; gib die jeweiligen Bedingungen und Jahre an.','Wende L, O und K auf dasselbe Projekt an. Kennzeichne mögliche mehrere Begründungen und unterscheide allgemeine Infrastruktur von dauernder Einzelbegünstigung.','Entwickle ein begründetes, bedingtes Urteil über B bei freien gegenüber ausgelasteten Kapazitäten; prüfe Zeit, Budget und Datenlücke.'],
['Classify R/S by order/process role and mechanisms; why is duration insufficient?','Connect R/S to L,O,K through enforcement and bounded demand effects.','Assess R+S and “Everything public is K”, identifying finance and a limiting condition.','For B, separate short-run construction demand and long-run access/productivity mechanisms, with years/conditions.','Apply L,O,K to the same project, admitting multiple reasons and distinguishing general infrastructure/selective favouritism.','Give a conditional judgment under spare/full capacity, examining timing, budget and missing evidence.'],
['R verändert Marktregeln, Kartell-/Zugangskontrolle; S beeinflusst zusätzliche aktuelle Aufträge/Auslastung. Auch befristete Regeln können Ordnung gestalten und dauerhafte Programme Nachfrage wirken: Zweck/Ausgestaltung zählen.','O stützt Wettbewerbsdurchsetzung in R; L kann allgemein offene Regeln akzeptieren, ohne jede Aufsicht abzulehnen. K begründet S aus Auslastung/Nachfrage, solange Mittel nicht vollständig andere wirksame Nachfrage verdrängen. Keine reine Staatsaktivitätszuordnung.','Wettbewerbliche Vergabe kann Ordnungsrahmen und befristeten Impuls verbinden. Gleiche10 verdrängen andere Leistungen; freie passende Ressourcen und tatsächliche Zusätzlichkeit prüfen. Alles Staatliche=K ist falsch, denn R regelt Wettbewerb.','Jahr1 Bauaufträge mit möglicherweise höherer Nachfrage/Auslastung; abJahr3 niedrigere Transportkosten/Zugang kann Produktivität/Konkurrenz verbessern. Beide hängen von Arbeitskräften, technischer Fertigstellung und Nutzung ab.','K: kurzfristiger Impuls bei Nachfragemangel. O: gleiche Zugangsbedingungen und Konkurrenz. L: allgemeine nutzbare Infrastruktur kann begründbar sein, nicht automatisch Zustimmung zu jedem Eingriff. Mehrere Zwecke möglich; allein das Wort Infrastruktur setzt keine Schule.','Bei freien Ressourcen kann Bau Menge/Beschäftigung stützen; bei Vollauslastung drohen Verdrängung/Preisdruck.20Budget fehlt woanders und spätere Nutzung ist unsicher. Etappen oder begründetes Verschieben sind zulässig; tatsächliche Vergabe/Nutzung später prüfen.'],
['R changes market rules/cartel-entry enforcement; S changes current orders/utilisation. Duration is insufficient: design/purpose determine the role.','O supports enforceable competition; L can accept general open rules rather than reject all enforcement. K supports S under demand shortfall, with displacement limits. Public activity alone proves no school.','Competitive procurement may combine order/demand functions.10displaces other uses; check suitable spare resources/additionality. R alone disproves “all public action is K”.','Year1construction may raise demand/utilisation; fromyear3transport access may improve productivity/competition. Labour, completion and use are conditions.','K: demand while idle; O: equal access/competition; L: general infrastructure may be defensible without blanket acceptance. Multiple reasons fit; the infrastructure label is insufficient.','Idle resources may allow output/jobs; full utilisation may mean crowding/prices.20displaces alternatives; future use remains uncertain. Staging/delay can be justified, with later delivery/use checks.'],
['2 BE für R/S funktional getrennt; 2 für Wirkungswege statt bloßem Daueretikett.','2 BE für L/O konkret und differenziert; 2 für K am Nachfrage-/Auslastungsmechanismus.','2 BE für begründete Kombination/Gegenbehauptung; 2 für Finanzierung und überprüfbare Grenze.','2 BE für kurzfristigen Kanal; 2 für langfristigen Kanal mit Bedingungen und Zeit.','2 BE für alle drei fallgebundenen Begründungen; 2 für Mehrfachfunktion und Grenze der Einzelbegünstigung.','2 BE für freie/ausgelastete Ressourcenfolgen; 2 für budget-/zeitgebundenes Urteil und Evidenzlücke.'],
['2for separate R/S functions;2for mechanisms beyond duration.','2for specific L/O;2for K demand/utilisation.','2for combination/counterclaim;2for funding and a testable limit.','2for short-run mechanism;2for long-run mechanism/time/conditions.','2for all three specific rationales;2for multiple functions/selective-subsidy limit.','2for spare/full-capacity consequences;2for budget/time judgment and evidence gap.'],
'Ordnungspolitik am tatsächlichen Regel-/Institutionenmechanismus; Prozesspolitik am tatsächlichen Nachfrage-/Ablaufmechanismus; begründete konkrete Zuordnung zu jedem der vorgelegten L-, O- und K-Rahmen; unterschiedliche kurz- und langfristige Funktionen desselben Investitionsprogramms',
'the institutional mechanism of order policy; the activity/demand mechanism of process policy; reasoned specific use of each L,O,K frame; distinct short- and long-run functions of the same investment')
add('7d399b4d','Digitaler Dienst und bezahlte Vergleichsplätze','Digital service and paid comparison placements',
'''**Fiktives Unterrichtsdossier, Stand 10.10.2026.** Es gibt keine realen KI-Leistungsdaten und keine vollständige Darstellung des geltenden Rechts. Die genannten Regeln sind ausdrücklich für den Modellvertrag festgelegt; ihre Anwendung ist vom eigenen Werturteil zu trennen.
**A:** Ein Auskunftsdienst beantwortet100 Anfragen. Vorher durchschnittlich10, digital6 Minuten Wartezeit; im Pilot8 falsche Antworten, deren Folgen von korrigierbaren Wegauskünften bis versäumten Fristen reichen. Kosten je Anfrage vorher5€, digital3€ vor menschlicher Kontrolle. Vertrag: richtige Auskunft oder rechtzeitige menschliche Prüfung; jeder Fehlfall muss eine kostenfreie menschliche Beschwerdemöglichkeit haben. Entwurf bietet nur einen automatischen Wiederholungsbutton. Option P kontrolliert alle100Antworten für zusätzlich2€ jeAnfrage; Option Q kontrolliert die20fristkritischen Antworten für zusätzlich2€ jekontrollierterAnfrage und bietet allen einen menschlichen Beschwerdeweg, Qualität bei anderen Antworten bleibt ungeklärt. Vergleich ohne Kontrollgruppe/gleiche Fallmischung.
**B:** Preisportal listet Angebote80€,90€,100€; Anbieter100bezahlt für Platz1. Modellregel: bezahlte Plätze müssen eindeutig als Werbung gekennzeichnet sein. Entwurf sagt nur „beste Wahl“ und verschweigt Bezahlung. Option L kennzeichnet bezahlte Position und zeigt auf Wunsch echte Preissortierung; Option I verzichtet auf bezahlte Rangplätze, verlangt Nutzungsgebühr2€. Gleiche Leistungen sind im Modell angenommen, Lieferbedingungen und Auswahlvollständigkeit fehlen. Zwei Nutzergruppen: regelmäßige preisempfindliche Käufer und seltene Nutzer ohne sicheres digitales Verständnis.''',
'''**Fictional classroom dossier dated10October2026.** No actual AI performance or complete live-law account is asserted. Rules are expressly stipulated model-contract criteria; applying them differs from normative judgment.
**A:** Service100queries: average wait10before and6digital minutes;8pilot errors, ranging from correctable directions to missed deadlines. Cost5before/3digital perquery before review. Contract: correct information or timely human review; every error case must have free human complaint access. Draft offers only automatic repetition. P reviews all100for extra2perquery. Q reviews20deadline-critical cases for extra2each and gives human complaint access to all; other accuracy is unresolved. No control group/equal case mix.
**B:** Portal offers80/90/100euros; supplier100pays for position1. Model rule: paid positions must be clearly labelled advertising. Draft says only “best choice”, concealing payment. L labels payment and offers actual price sorting; I removes paid placement and charges2userfee. Equal service is assumed; delivery terms/completeness are unknown. Frequent price-sensitive buyers and occasional users with limited digital understanding are distinct groups.''',
['Für A: Berechne Zeitänderung, Fehleranteil und Gesamtkosten von P/Q. Analysiere mindestens zwei wirtschaftliche Folgen mit ihren Datenbedingungen.','Wende beide Vertragsanforderungen auf Entwurf und Q an. Unterscheide festgestellten Regelmangel und noch offene Qualität; automatische Wiederholung ist nicht menschliche Beschwerde.','Beurteile P/Q anhand expliziter Zugangs-, Kosten- und Fehlerfolgenkriterien. Entwirf eine materialbezogene Verbesserung und nenne benötigte Wirkungs-/Vergleichsdaten.','Für B: Erkläre Suchkostenvorteil und bezahlten Rangplatzanreiz. Berechne die mögliche Ersparnis des80€-Angebots gegenüber100€ und ihren Nettowert mit Gebühr2€.','Wende die vorgelegte Kennzeichnungsregel an. Unterscheide regelkonforme Kennzeichnung, unabhängige Sortierung und tatsächlichen Vergleich; prüfe Entwurf/L/I.','Beurteile L/I für beide Nutzergruppen und Anbieter. Begründe ein ergebnisoffenes Urteil mit Daten-/Normgrenze; weder günstigster Preis noch Digitalisierung beweist allgemeine Zulässigkeit.'],
['For A, calculate waiting change, error rate and P/Q total costs; analyse two economic effects with conditions.','Apply both contract requirements to draft/Q, separating a rule breach from unresolved quality; repetition is not human complaint access.','Assess P/Q by access,cost,error consequences; propose a dossier-based remedy and missing comparison/outcome evidence.','For B, explain search-cost benefit and paid-rank incentive. Calculate80-versus100saving and net saving after fee2.','Apply the supplied advertising rule, distinguishing labelling, independent sorting and actual comparison for draft/L/I.','Assess L/I for both user groups and suppliers; justify an open judgment with evidence/legal boundaries.'],
['10→6:−4min/−40%;8/100=8%. P=100×(3+2)=500€, Q=100×3+20×2=340€. P beseitigt Kostenvorteil gegenüber500früher; Q spart160unter Annahmen, aber gemischte Fristen-/Fehlerfolgen und Zugang sind nicht im Kostensaldo bewiesen.','Entwurf verletzt ausdrücklich menschlichen Beschwerdeweg. Q erfüllt dessen Zugangsanforderung, sofern tatsächlich kostenlos/menschlich; Kontrolle20garantiert weder alle richtigen Antworten noch rechtzeitige Prüfung jedes Fehlfalls. Vollständige reale Rechtsfreigabe folgt nicht aus Modellvertrag.','Qualität/Fristen, verständlicher erreichbarer Beschwerdeweg und Kosten gewichten. P kann Fristfehler eher erkennen, bleibt zeitlich zu prüfen; Q kann kostengünstiger sein, benötigt überprüfbares Eskalationsverfahren und Qualitätsstichprobe. Gleiche Fallmischung, Folgeschäden, Kontrollverzögerung erheben, keine allgemeine KI-Überlegenheit.','Portal kann Suchzeit senken, aber Position1motiviert Anbieter100zumZahlen und lenkt Auswahl.100−80=20€, relativ20%; mit2Gebühr netto18€, falls Kauf/gleiche Leistung tatsächlich zutrifft. Seltene Nichtkäufer tragen Gebühr ohne Ersparnis.','Entwurf kennzeichnet Bezahlung nicht eindeutig. L erfüllt bereitgestellte Kennzeichnungsregel, sofern deutlich; bezahlte Rangliste bleibt auch mit Label nicht unabhängig. Echte Preisordnung ist eine andere Funktion. I braucht kein Label für abgeschaffte Werbung, ist damit nicht automatisch nach allen realen Normen zulässig.','L kann günstigen Zugang und Erlöse verbinden, verlangt sichtbares verständliches Label/Sortierwahl; I senkt Rangverzerrung, belastet gelegentliche Nutzer. Anbieteranreize, Auswahl/Lieferbedingungen und Verständnis prüfen. Begründete Wahl ist offen; Modellregel, wirtschaftlicher Nutzen und umfassende Rechtslage bleiben getrennt.'],
['Wait−4minutes/−40%;error8%. P100×5=500;Q300+40=340. Premoves savings versus prior500;Q saves160conditionally, not proving access/quality or deadline protection.','Draft lacks required human complaints. Q meets that component only if genuinely free/human;20checks do not guarantee all correct answers/timely review. A model contract is not complete legal approval.','Weight deadlines,accessible complaint paths and costs. Pmay identify more errors but needs timing;Qneeds checkable escalation/quality sampling. Compare similar case mixes and later harms/delays, not universal AI superiority.','Search costs may fall; supplier100pays to steer choice. Saving20/20%,net18afterfee2if a purchase/equal service actually applies. Occasional nonbuyers may pay without benefit.','Draft conceals payment. Lcan satisfy clear advertising disclosure while remaining a paid ranking. Independent price sorting is separate. Iremoves paid positions but does not establish compliance with all actual law.','Lallows lower access cost/revenue with understandable labelling/sort choice. Ireduces ranking bias but burdens occasional users. Examine suppliers,coverage/terms and comprehension; conclusions remain open and bounded.'],
['2 BE für Zeit-/Fehler-/Kostenrechnung; 2 für zwei bedingte wirtschaftliche Folgen.','2 BE für konkrete Beschwerderegelanwendung; 2 für Qualitäts-/Zeitpflicht und deren offene Grenze.','2 BE für explizite Kriterien/bedingtes Urteil; 2 für echte Verbesserung und benötigten Vergleich.','2 BE für Suchkosten-/Ranganreiz; 2 für20/18 und richtige Nutzer-/Modellgrenze.','2 BE für tatsächliche Kennzeichnungsanwendung; 2 für Label/Sortierung/umfassende Normgrenze getrennt.','2 BE für beide Nutzergruppen/Anbieter; 2 für begründetes Urteil und konkrete Daten-/Normgrenze.'],
['2for time/error/cost calculation;2for two conditional economic effects.','2for complaint-rule application;2for quality/timing requirement and its limits.','2for criteria/conditional judgment;2for a real remedy and needed comparison.','2for search/ranking mechanisms;2for20/18and model/user limits.','2for disclosure-rule application;2for label/sorting/general-law distinction.','2for both user groups/suppliers;2for a reasoned judgment and evidence/legal limits.'],
'wirtschaftliche Anreiz-/Kosten-/Qualitätsanalyse am konkreten Digitalfall; tatsächliche Anwendung der jeweils vorgelegten Vertrags- oder Kennzeichnungsregel; eine kriterienspezifische begründete Bewertung; die Unterscheidung Datenhinweis, Modellrechtsmaßstab und umfassender rechtlicher oder kausaler Schlussfolgerung',
'specific economic incentive/cost/quality analysis; actual application of each supplied contract/disclosure criterion; a reasoned criterion-based evaluation; distinction of evidence, model legal criteria and comprehensive legal/causal conclusions')
add('94264f00','Datierte Tarifpositionen und begrenzte Einkommensanteile','Dated bargaining positions and bounded income shares',
'''**Tatsächliche Positionen, Material gelesen 10.10.2026:** [IG Metall](https://www.igmetall.de/tarif/tarifrunden/metall-und-elektro/tarifrunde-metall-und-elektro-2026), 23.09., aktualisiert01.10.2026, fordert5% Entgelt, Beschäftigungssicherung und Gewinnbeteiligung bei erfolgreichen Betrieben. [Gesamtmetall](https://www.gesamtmetall.de/wir-haben-nicht-den-luxus-ueber-die-verteilung-von-zuwaechsen-verhandeln-zu-koennen/),23.09.2026, widerspricht mit Rentabilitäts-, Kosten- und Standortargumenten. Dies sind Interessenpositionen, kein heutiger Tarifabschluss und kein neutraler Wirkungsbeweis.
**A — erfundenes Zwei-Einkommensmodell:** Gesamteinkommen100=Arbeitnehmerentgelt60+Gewinn40. Beschäftigung, Einkommen und Produktivität bleiben für die Anteilsrechnung ausdrücklich gleich. Eine modellierte5%-Erhöhung des Entgelts wird vom Gewinn umverteilt. Freie Kapazität und mögliche Mehrnachfrage sind gegeben, Ausgabenreaktion und Preisweitergabe nicht.
**B — unabhängiger Modellfall:** Einkommen100=Entgelt50+Gewinn50; Bonus4wird einmalig vom Gewinn zu Entgelt umverteilt, Einkommen/Beschäftigung gleich. Ein erfolgreicher Betrieb meldet steigende Produktivität und gute Aufträge. Ein Krisenbetrieb hat schwache Aufträge und keine überschüssigen Mittel; seine tatsächlichen Einkommenszahlen fehlen. Der4Bonusfall ist keine vorgeschriebene nationale Quote oder realer tariflicher Anspruch. Eine spätere Produktivitäts-/Preisänderung darf den Modellnenner ändern; sie ist nicht quantifiziert.''',
'''**Actual positions read10October2026:** [IG Metall](https://www.igmetall.de/tarif/tarifrunden/metall-und-elektro/tarifrunde-metall-und-elektro-2026),23September,updated1October2026, demands5%pay, job security and profit participation at successful firms. [Gesamtmetall](https://www.gesamtmetall.de/wir-haben-nicht-den-luxus-ueber-die-verteilung-von-zuwaechsen-verhandeln-zu-koennen/),23September2026,objects on profitability,costs and location. These are interested positions,not a current settlement or neutral proof of effects.
**A — invented two-income model:** total100=compensation60+profit40. Employment,total income,productivity explicitly fixed for share arithmetic. A model5%payrise reallocates profit to compensation. Spare capacity/possible extra demand are given; spending response/pass-through are not.
**B — independent model:** total100=pay50+profit50; a one-off4bonus reallocates profit to pay with income/employment fixed. Successful firm: rising productivity/good orders. Distressed firm: weak orders/no spare funds, actual income amounts unknown.4is no official national share or existing entitlement. Later productivity/prices may change the denominator but are unquantified.''',
['Für A: Gib beide tatsächlichen datierten Positionen mit Interesse wieder; trenne Forderung, Befund und Abschluss.','Berechne Entgelt/Gewinn sowie beide Anteile vor/nach5%. Erkläre den gemeinsamen Nenner und die Grenze zur amtlichen nationalen Lohn-/Gewinnquote.','Beurteile A im Hinblick auf Wachstum und getrennt Beschäftigung: verbinde Kaufkraft-/Nachfragekanal mit Kosten-/Gewinn-/Investitionskanal und Bedingungen.','Für B: Vergleiche Gewinnbeteiligung mit dauerhafter Entgelterhöhung und ordne beide Parteiargumente der unterschiedlichen Betriebslage zu.','Berechne beide Einkommen/Anteile nachBonus4. Erkläre, was bei später geändertem Gesamteinkommen neu geprüft werden muss und weshalb keine Krisenbetriebsquote erfunden werden darf.','Entwickle ein bedingtes Urteil für Erfolgs- und Krisenbetrieb über Wachstum, Beschäftigung und Verteilung. Nenne fehlende Prüfgrößen; Parteibehauptungen sind nicht sichere Mehrjobs/Jobverluste.'],
['For A, report both dated interested positions; distinguish demand,evidence and settlement.','Calculate pay/profit and both shares before/after5%. Explain the shared denominator and the limit to official national accounts.','Assess growth and separately employment through purchasing-power/demand and cost/profit/investment mechanisms with conditions.','For B, compare profit participation/permanent pay rise and apply both party arguments to different firm situations.','Calculate both incomes/shares afterbonus4; explain a changed future denominator and why no distressed-firm share may be invented.','Give a conditional growth,employment,distribution judgment for both firms with needed evidence, not guaranteed jobs/losses.'],
['Gewerkschaft verfolgt Einkommen/Sicherheit/Teilhabe und argumentiert mit Kaufkraft; Arbeitgeber betont Kostentragfähigkeit/Standort. Quelle dokumentiert diese Positionen zuTerminen, nicht richtigen kausalen Ausgang oder Einigung.','60×1,05=63;Gewinn37; vorher60%/40%, danach63%/37%. Nenner100bleibt nur kraft Modellannahme; Gewinnquote komplementär. Weder Umsatzanteil noch echte nationale Verteilung wird gemessen.','Mögliche zusätzliche Ausgaben unterstützen Absatz/Produktion bei freien Ressourcen; höhere Kosten und geringere Gewinne können Investitionen belasten. Beschäftigung hängt getrennt von Absatz, Produktivität, Stunden, Preisen und Reaktion ab; Wachstum kann ohne proportionale Stellenänderung auftreten.','Bonus ist einmalige Umverteilung, dauerhafte Tabellenerhöhung wirkt auch später. Erfolg erlaubt mögliche Beteiligung, Krise begrenzt Finanzierbarkeit; Gewerkschaftsheterogenität und Arbeitgeberkostenargumente prüfen, nicht eine Lage der gesamtenBranche behaupten.','Entgelt54/Gewinn46;Anteile54%/46%. Bei veränderten Preisen/Produktivität/Einkommen ist tatsächlicher neuer Nenner zu erheben;54%ist dann nicht automatisch konstant. Ohne Krisenwerte kein neuer Anteil.','Bonus kann Kaufkraft/Teilhabe verbessern, aber Gewinne/Investitionsmittel senken; sichere Finanzierung/Liquidität und Auftrags-/Produktivitätsdaten prüfen. Krise kann Unterstützung/anders gestaltete Bindung brauchen. Growth/Jobs hängen von Nachfrage, Kosten, Investition und Zeit ab; kein automatischer nationaler Effekt.'],
['Union prioritises income/security/participation and purchasing power; employers cost viability/location. Dated statements document positions, not causal truth or an agreement.','60×1.05=63;profit37;shares60/40→63/37%.100is fixed only by assumption;profit share complements labour share. These are not revenue shares/national statistics.','Possible spending supports sales/output with idle resources; higher costs/lower profits can constrain investment. Jobs separately depend on sales,productivity,hours,prices and response; output growth is not proportional hiring.','A one-off bonus differs from lasting pay scales. Success may support participation; distress limits finance. Examine heterogeneous situations and both arguments instead of treating the entire sector alike.','Pay54/profit46,shares54/46%. A changed income/productivity/price denominator must be measured;54%would not automatically persist. Missing crisis figures cannot be invented.','Bonus may support demand/participation but reduce investment funds. Check liquidity,orders and productivity. Distress may warrant a different retention/support design. Growth/jobs depend on several timed channels, not guaranteed national changes.'],
['2 BE für beide datierte Interessenpositionen; 2 für Forderungs-/Befund-/Abschlussgrenze.','2 BE für63/37 und beide Anteilsverschiebungen; 2 für gemeinsamen Nenner und nationale Modellgrenze.','2 BE für begründete Wachstumsmechanismen; 2 für eigenständige Beschäftigungsbedingungen und Gegeneffekte.','2 BE für Einmalbonus/dauerhaften Lohn getrennt; 2 für beide Positionen unter unterschiedlichen Betriebslagen.','2 BE für54/46 und beide Anteile; 2 für neuen Nenner/fehlende Krisenwerte.','2 BE für bedingte Wachstums-/Beschäftigungsabwägung beider Lagen; 2 für Verteilung und konkrete Evidenzanforderung.'],
['2for both dated interests;2for demand/evidence/agreement distinction.','2for63/37and both share changes;2for shared denominator/national limit.','2for growth channels;2for distinct job conditions/opposing effects.','2for bonus/permanent pay distinction;2for both positions/different firms.','2for54/46and both shares;2for changed denominator/missing crisis figures.','2for conditional growth/jobs across both situations;2for distribution/evidence needs.'],
'beide tatsächlichen Interessenpositionen als datierte Forderungen; korrekt begrenzte Lohn- und Gewinnanteile mit gemeinsamem Nenner; eigenständig begründete Wachstumswirkungen; eigenständig begründete Beschäftigungswirkungen; bedingte Verteilungs-/Kostenabwägung verschiedener Betriebslagen',
'both actual dated interested positions; bounded labour and profit shares with a common denominator; distinct reasoned growth effects; distinct reasoned employment effects; conditional distribution/cost trade-offs across different firms')
add('b84f3f68','Umschulung mit Vergleich, Zugang und Zusatzwirkung','Retraining with comparison, access and additionality',
'''Alle Personen, Programme und Zahlen sind fiktiv; keine privaten Lernendeninformationen sind nötig.
**A:**100Teilnehmende/100Vergleichspersonen, anfangs je40beschäftigt; während sechsmonatigem Kurs30gegen45, nach18Monaten70gegen60. Gruppen haben gleiche beobachtete Alters-/Berufsanteile, Teilnehmende aber möglicherweise mehr Motivation; Zuweisung nicht zufällig. Kosten300.000€.100nehmen teil,90schließen ab,80haben passenden Nachweis,60arbeiten im Zielberuf; Zahlen bezeichnen überlappende aufeinanderfolgende Gruppen. Arbeitgeber melden freie passende Stellen, dauerhafte Qualität/Lohn fehlt.
**B:** Anpassungsqualifizierung für100Routinebeschäftigte kostet200.000€, bei zusätzlicher Kinderbetreuung50.000€.80haben digitalen Zugang;20nicht. Ohne Betreuung können30Interessierte trotz Eignung nicht teilnehmen.80Abschlüsse,60Einstellungen:40imZielberuf,20anders; von40Zielberufseinstellungen wären10laut dokumentiertem Betriebsplan ohnehin nach ungeförderter Schulung erfolgt. Ein Betrieb ersetzt möglicherweise5geplante ungeförderte Bewerbereinstellungen durch geförderte Personen; ob dies zusätzliche Verdrängung oder dieselben10sind, ist ungeklärt.50passende Stellen gemeldet, Stellenqualität und tatsächliche offene Nachfrage nach12Monaten fehlen. Vergleichsgruppe und mehrjährige Verläufe sind noch nicht erhoben.''',
'''All people,programmes and figures are fictional; no private learner information is needed.
**A:**100participants/100comparators,initially40employed in each; during a six-month course30versus45, after18months70versus60. Observed age/occupation mixes match, but motivation may differ; allocation nonrandom. Cost300,000.100attend,90complete,80have matching certification,60work in the target occupation; these are overlapping sequential groups. Employers report suitable vacancies; lasting quality/pay are unknown.
**B:** Skills adjustment100routine workers costs200,000,plus50,000optional childcare.80have digital access,20do not. Without care30suitable interested people cannot attend.80complete,60are hired:40target jobs,20other. Plans indicate10of40target hires would happen after unfunded training anyway. One firm may replace5planned unsubsidised applicant hires with subsidised people; overlap with the10is unknown.50suitable vacancies are reported, but job quality/actual demand after12months are unknown. No comparison/multi-year data yet.''',
['Für A: Berechne Kurs-/Nachlaufunterschiede und Veränderungen; unterscheide Lock-in von längerfristiger Beschäftigungsentwicklung.','Unterscheide Teilnahme, Abschluss, Qualifikationsnachweis und tatsächlich genutzte Beschäftigung. Berechne eine klar benannte Kostenquote und prüfe Vergleichbarkeit/Gegenentwicklung.','Beurteile A nach Passung, Zugang, Kosten, kurz-/langfristigem Nutzen. Entwirf eine verlässlichere Evaluation ohne automatischen Kausalitätsanspruch.','Für B: Analysiere reale Zugangsbarrieren, Qualifikations-/Nachfragepassung und verschiedene Ergebnisstufen;100Teilnahmen sind keine100Jobs.','Untersuche Mitnahme und mögliche Verdrängung am Material. Berechne Zusatzbudget und beschreibende Kosten jeZielberufseinstellung; addiere unklare überlappende Mengen nicht als sichere Zusatzwirkung.','Beurteile B mit begründeter Förder-/Umsetzungsoption und Finanzierung. Nenne Gegenentwicklung, Zeithorizont und Qualitätsdaten, die für die Entscheidung fehlen.'],
['For A, calculate course/follow-up differences and changes; distinguish lock-in from later employment.','Separate attendance,completion,certification and actual occupational use. Calculate a named cost ratio and examine comparability/counterfactual.','Assess fit,access,costs,short/long benefit; design better evaluation without automatic causality.','For B, analyse access barriers,skill/demand fit and outcome stages;100attendances are not100jobs.','Examine deadweight/displacement; calculate extra budget and descriptive cost per target hire without summing uncertain overlaps.','Give a funded implementation judgment with missing counterfactual,horizon and job-quality evidence.'],
['Kurs30−45=−15pp;später70−60=+10pp;Veränderungen+30/+20pp. Während Qualifizierung wenigerSuche kann kurzfristigen Lock-in bedeuten, nicht allein endgültigesScheitern; späterer Unterschied kein sicherer kausalerGewinn.','100Teilnahme/90Abschluss/80Nachweis/60Zielberuf sind verschiedene überlappende Stufen.300.000/60=5.000€beschreibend jeZieljob;300.000/10=30.000wäre nur unter unbewiesener Kausalitäts-/Zusatzjobannahme. Beobachtete Vergleichbarkeit schützt nicht vor Motivationsselektion/anderen Trends.','Passender Bedarfsbezug spricht bedingt dafür, Qualität/Haltedauer/Kosten/Barrieren offen. Vorabverläufe, ähnliche Vergleichspersonen, mehrere Zeitpunkte, Jobqualität und robuste Zuweisung prüfen; langfristigen Nutzen gegen Kurszeitkosten abwägen.','Digitale20undBetreuung30können sich überlappen; Zugangshilfen zielgerichtet, nicht als sichere50zusätzlicheTeilnehmer addieren.80Abschluss und40Zieljob verschieden;50gemeldeteStellen brauchen passende Qualität und realen Bedarf.','Mitnahme10sind ohnehin geplante Zieljobs; möglicheVerdrängung5ändert andere Bewerberchancen. Überlappung unklar, daher nicht sicher40−10−5=25kausaleJobs. MitBetreuung250.000,40Zieljobs→6.250€beschreibend;ohne200.000/40=5.000. Keine Kostenquote pro erwiesenem Zusatzjob.','Care/digitalerZugang können Teilhabe stärken, fördern aber nicht automatisch passende Stellen.250.000verdrängt alternativesBudget, Firmenpläne/Zusatznachfrage prüfen. Vergleich ohne Förderung, dauerhafte Stellen nach12/24Monaten, Qualität/Gruppe und mögliche Verdrängung erheben; bedingtesPiloturteil oder begründeteAblehnung zulässig.'],
['Course−15pp,follow-up+10pp,changes+30/+20pp. Reduced search during training may be lock-in,not final failure; later differences are not proven causal gains.','100attendance/90completion/80certification/60target jobs overlap sequentially.300,000/60=5,000descriptive per target job.30,000peradditional job would require unproved causality. Observable matching leaves motivation/other trends unresolved.','Demand fit supports a conditional case; duration,quality,cost and access remain open. Check pretrends,similar controls,several horizons,job quality and credible allocation; weigh course opportunity cost/long-run use.','20digital/30care barriers may overlap; do not invent50extra participants.80completions/40target jobs differ;50reported vacancies need matching skills,quality and actual demand.','10planned hires imply deadweight;5replacement may displace others. Unknown overlap means40−10−5is not25proven additional jobs. Care raises budget to250,000,descriptive6,250per40target hires versus5,000without;not causal extra-job cost.','Care/digital support may improve access without guaranteeing jobs.250,000displaces alternatives; examine firm plans/additional demand. Collect no-programme comparison,12/24month quality/durability and displacement evidence; a conditional pilot or reasoned rejection is acceptable.'],
['2 BE für−15/+10/+30/+20 und richtige Einheiten; 2 für Lock-in/Nachlauf getrennt.','2 BE für vier Ergebnisstufen/Kostenquote; 2 für plausible Gegenentwicklung und Selektionsgrenze.','2 BE für Passung/Zugang/Kosten/Zeiturteil; 2 für tatsächliche Evaluationsverbesserung.','2 BE für zwei Zugangsbarrieren ohne Doppelzählung; 2 für Qualifikation, Zieljob und Nachfragepassung.','2 BE für Mitnahme/Verdrängung mit Überlappungsgrenze; 2 für200/250Tsd und5.000/6.250 klar beschreibend.','2 BE für finanzierbare Umsetzung/bedingtes Urteil; 2 für Gegenentwicklung, Zeit und benötigte Qualität.'],
['2for−15/+10/+30/+20with units;2for lock-in/follow-up distinction.','2for stages/cost ratio;2for plausible counterfactual/selection limit.','2for fit/access/cost/horizon judgment;2for real evaluation improvement.','2for both access barriers/overlap;2for skill,job,demand fit.','2for deadweight/displacement/overlap;2for budgets/descriptive cost ratios.','2for funded implementation/conditional judgment;2for counterfactual,time,quality evidence.'],
'unterschiedliche Teilnahme-/Abschluss-/Beschäftigungsstufen; kurzfristiger Lock-in und späterer Verlauf; eine plausible Gegenentwicklung mit kausaler Auswahlgrenze; Zugangs-/Qualifikations-/Nachfragepassung; eigenständig behandelte Mitnahme und eigenständig behandelte Verdrängung; eine kosten- und zeitgebundene Bewertung',
'distinct participation/completion/employment stages; short-run lock-in and later outcomes; plausible counterfactual and causal selection limit; access/skills/demand fit; separately considered deadweight and separately considered displacement; a cost- and horizon-bound judgment')
add('7727b988','Reparaturbetrieb und regionaler Qualifikationsübergang','Repair business and regional skills transition',
'''Alle Zahlen/Szenarien sind fiktiv; es sind keine Prognosewahrscheinlichkeiten gegeben.
**A — Betrieb, drei Jahre:** Anfangsliquidität60.000€. Sofort große Werkstatt kostet50.000, Stufenausbau20.000 jetzt und optional30.000später, Weiterbildung10.000. Mindestliquiditätsreserve15.000. Prognose ist offen: hohe Reparaturnachfrage/niedrige Energiekosten gegenüber schwacher Nachfrage/hohen Energiekosten. BestehendeWerkstatt kann30Aufträge/Woche, Stufe40, groß60; ungewisser tatsächlicher Bedarf25oder50. BeihoherNachfrage kann ein kleiner Ausbau Engpass verursachen; Energiekosten treffen jede genutzte Kapazität. Keine zusätzlichen Kreditmittel sind zugesagt.
**B — Region, zehn Jahre:** Budget12Mio€. MobileWeiterbildung4, Breitband-/Zugangsprojekt6, Übergangsunterstützung2; gemeinsam12. Alternative zentralesHightechzentrum12ohneZugangshilfe. Rahmenannahmen: breiter/ungleicherQualifikationszugang und schnell/langsam entstehende neue Tätigkeiten. Umsetzungskapazität ist auf eine große Infrastrukturbaustelle gleichzeitig begrenzt. Ungewiss sind Beschäftigung, Kostenfortschreibung und Nutzung. Entwirf mindestens zwei konsistente Zukunftsbilder für jeden Fall; keine Prozentwahrscheinlichkeiten erfinden.''',
'''All figures/scenarios are fictional; no forecast probabilities are supplied.
**A — business,three years:** cash60,000. Large workshop costs50,000now; staging20,000now/optional30,000later;training10,000. Minimum cash buffer15,000. Uncertain high repair demand/low energy costs versus weak demand/high energy costs. Weekly capacity30existing/40stage/60large;actual demand25or50unknown. Staging may constrain high demand; energy affects used capacity. No extra loan is promised.
**B — region,ten years:** budget12million. Mobile training4,broadband/access6,transition support2,total12. Alternative central high-tech centre12without access assistance. Drivers: broad/unequal skills access and rapidly/slowly emerging activities. Only one major infrastructure build can run at once; jobs,costs,use uncertain. Develop at least two internally coherent futures for each case without invented probabilities.''',
['Für A: Entwickle die beiden unterschiedlichen Zukunftsbilder mit Nachfrage/Energie, Mengen-/Kosten-/Liquiditätsfolgen und offengelegten Annahmen.','Vergleiche großeWerkstatt,Stufen undWeiterbildung unterReserve/Budget; rechne sofortigeRestliquidität und einen möglichen Engpass.','Begründe eine robuste oder szenariospezifische Wahl mit Zielkonflikt und konkretem Anpassungssignal; bedingtes Bild ist keine sichere Prognose.','Für B: Entwickle mindestens zwei konsistente Bilder aus Zugang und neuerTätigkeitsentstehung; erkläre Beschäftigungs-/Verteilungsfolgen statt Technikautomatismus.','Vergleiche beideBudgetoptionen mit Teilhabe, Kosten, Umsetzung und Bedingungen. Entwickle eine robuste Maßnahme sowie eine szenariospezifische Reaktion.','Beurteile eigene Szenarien/Optionen mit Unsicherheit, Zeit und konkretem Revisionssignal. Eine andere begründete Strategie ist zulässig; Eintrittswahrscheinlichkeiten sind nichtgegeben.'],
['For A,develop both demand/energy scenarios with quantity,cost,liquidity consequences and assumptions.','Compare large,staged,training options under budget/reserve; calculate immediate cash and a possible capacity shortfall.','Justify a robust/scenario-specific choice,trade-off and adaptation signal; scenario is not certainty.','For B,develop two coherent access/activity scenarios and employment/distribution implications without technological automatism.','Compare both budgets by inclusion,cost,implementation and conditions; propose robust and scenario-specific steps.','Assess uncertainty,time and a concrete review trigger; other justified strategies count,probabilities are not given.'],
['Hoch/niedrig:E50Aufträge kann bestehende30überlasten, niedrigereEnergiekosten können Spielraum geben, aber nicht sichereGewinne. Schwach/hoch:25unter30, ungenutzte großeKapazität undhoheKosten bedrohenReserve. Annahmen müssen zusammenpassen, Kostenzahlen/Erträge fehlen.','Groß:60.000−50.000=10.000unterReserve15.000;mitTraining0. Stufe:40.000,mitTraining30.000;Trainingallein50.000. Stufe40gegenBedarf50→10Engpass, bestehend30→20. Später30.000istnichtausheutigerRestreservefrei: Mittelzufluss/neueFinanzierung prüfen.','Stufe+Training bewahrt30.000undReversibilität, begrenzt Kapazität; hohe stabileAufträge können Mehrbau verlangen. Zwei oder mehrere nachgewieseneMonate tragfähigerAufträge/Reserve nach Ausbau≥15.000sind einPrüfsignal, keine garantierteZukunft. GroßeWerkstatt erst mit belegtem zusätzlichemFinanzierungsraum vertretbar.','BreiterZugang/schnelleTätigkeiten kann Übergänge/Teilhabe erleichtern, Fähigkeiten/Nutzung dennoch nötig. UngleicherZugang/langsameTätigkeiten kann Gruppen ausschließen und Friktionsarbeitslosigkeit verlängern; weder Digitalisierung=alleJobsweg noch automatischeWohlstandssteigerung.','4+6+2=12;Training/Zugang/Übergang können mehrerenBildern nützen, auchsie brauchen Anbieter/Kapazität/Nutzung. Zentrum12konzentriertMittel, brauchtErreichbarkeit/Bedarf; konkurrierendeBauten nichtparallelplanen. LangsamesEntstehen spricht für anpassbareHilfe/Etappen.','Jährlich tatsächlicheZugänge, passendeStellen/Abschlüsse undBudget beobachten; beiAusgrenzung/mobileAngebote anpassen, beiKostenanstieg priorisieren. Keine nichtgegebenenWahrscheinlichkeiten/Gewinne. Optionen anhand offenerAnnahmen/Verteilung/Ressourcen neuprüfen.'],
['High/low:50orders may exceed30capacity; cheaper energy may ease costs but no profit is certain. Weak/high:25below30;unused large capacity/high costs threaten buffers. State assumptions;costs/returns unknown.','Large leaves10,000below15,000buffer;withtraining0. Stage leaves40,000,withtraining30,000;trainingalone50,000. Capacity40versus50means10shortfall;existing30means20. Later30,000requires inflows/funding,not free reserve.','Stage+training retains30,000/flexibility but may bottleneck. Sustained viable orders and post-expansionbuffer≥15,000can trigger review,not certainty. Large build needs demonstrated financing.','Broad access/fast activity may ease transitions if skills/use fit. Unequal access/slow emergence may exclude groups/prolong friction. Technology guarantees neither alljobloss nor prosperity.','4+6+2=12. Training/access/transition may help across scenarios with provider/use/capacity conditions. Centre12concentrates resources,needs demand/reach;do not plan parallel major builds. Slow emergence supports reversible assistance/staging.','Review actual access,target jobs/completion,budget annually;adapt mobile provision after exclusion/prioritise after cost rises. No invented probabilities/profits. Reassess assumptions,distribution,resources.'],
['2 BE für zwei intern konsistente A-Bilder; 2 für verknüpfte Mengen-/Kosten-/Liquiditätsfolgen und Annahmen.','2 BE für Restliquidität/Reserve; 2 für tatsächlichen Kapazitätsengpass und spätereFinanzierungsgrenze.','2 BE für begründete Robustheit/Zielkonflikt; 2 für konkretes Anpassungssignal und Prognosegrenze.','2 BE für zwei konsistente B-Bilder; 2 für Zugang/Beschäftigung/Verteilung ohne Automatismus.','2 BE fürBudget undUmsetzung beiderAlternativen; 2 für robuste und bedingteMaßnahme mitVoraussetzung.','2 BE für überprüfbareRevisionssignale; 2 für tatsächliche Unsicherheit/Zeit-/Ressourcengrenze.'],
['2for two coherent A futures;2for linked quantity,cost,cash assumptions.','2for cash/reserve;2for capacity/later-finance limit.','2for robustness/trade-off;2for adaptation signal/forecast distinction.','2for two coherent B futures;2for access/jobs/distribution without automatism.','2for budgets/implementation of both;2for robust/conditional action and conditions.','2for concrete revision signals;2for real uncertainty/time/resource limits.'],
'mindestens zwei unterschiedliche konsistente Zukunftsbilder unter je offengelegten Annahmen; Entwicklung und Beurteilung konkreter Gestaltungsoptionen; Ressourcen-/Finanzierungsbedingungen und Zielkonflikte; ein überprüfbares Anpassungssignal; Unterscheidung bedingter Szenarien von sicherer Prognose',
'at least two distinct coherent futures with explicit assumptions; developed and assessed concrete options; resource/funding conditions and trade-offs; a checkable adaptation signal; distinction of conditional scenarios and certainty')
add('94fe52f5','Vernetzte Energieentlastung und Zahlungsübergang','Connected energy relief and payment transition',
'''**Tatsächliche datierte Ausgangspunkte, gelesen10.10.2026:** [EZB10.09.2026](https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.mp260910~314e508016.en.html): Leitzinsen+25Basispunkte; Inflation-/Wachstumsaussichten unsicher. [EZB-Projektfortschritt](https://www.ecb.europa.eu/euro/digital_euro/progress/html/index.en.html): mögliche Ausgabe2029 unter notwendigerGesetzgebung, spätereAusgabeentscheidung bleibt nötig. Beide tatsächlichen Stände sind von nachfolgenden Unterrichtsmodellen getrennt.
**A — erfundene Energie-/Wachstumslage am10.10.2026:**100Haushalte,50besonders belastet, monatlicheEnergieausgabe100→120; Betrieb plant kreditfinanzierteEffizienzausrüstung, Aufträge/Preisweitergabe ungewiss. Einmaliges öffentlichesModellbudget12.000ist bereitsdurchUmwidmung finanziert, verdrängt andereLeistung12.000. PaketT:50×100zielgerichteteHilfe plus7.000Effizienz. PaketB:100×60breiteHilfe plus6.000Effizienz. Effizienz spart nicht sofort sicher Energie, braucht qualifizierteArbeit undUmsetzung. Der europäische Zinsschritt istgegeben; ein Kommunalrat kann ihn nicht selbstbeschließen.
**B — unabhängiges digitalesZahlungsmodell:**Keine heutigeAusgabe/Regel. BankanfangAktiva:Reserven20,Kredite80,andere40;Passiva:Einlagen100,Eigenkapital40. Öffentliche digitaleGeldhaltung10wird allein durch gleich hohenReserven-/Einlagenabgang abgewickelt, restlicheBilanz konstant. VarianteU:30UmwandlungohneweitereFinanzierungszusage, bisher20Reserven. FiktivesÜbergangsbudget6.000:gestufterPilot2.000,Beratung/zugänglicheKarte2.000,Technikprüfung2.000. Alternative breiteEinführung6.000ohneBetreuung; tatsächlicheTeilnahme/Kosten/Risiken fehlen. Bargeld bleibt imModellmöglich. WeitereRefinanzierung kann möglichsein, wird nichtgarantiert.''',
'''**Actual dated starting points read10October2026:** [ECB10September2026](https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.mp260910~314e508016.en.html):keyrates+25basispoints,uncertain inflation/growth. [ECB project progress](https://www.ecb.europa.eu/euro/digital_euro/progress/html/index.en.html):possible2029issuance requires legislation and a later issuance decision. These anchors differ from the following original models.
**A — invented energy/growth context dated10October2026:**100households,50particularly burdened,monthly energy100→120;a firm plans debt-financed efficiency equipment,orders/pass-through uncertain. One-off public12,000already funded by reallocation,displacing another12,000use. T:50×100targeted relief+7,000efficiency. B:100×60broad relief+6,000efficiency. Efficiency requires time,skills,delivery,no guaranteed immediate saving. The European rate move is given,a local council cannot set it.
**B — independent hypothetical digital payments:**No current issuance/rule. Initial bank assets:reserves20,loans80,other40;liabilities:deposits100,equity40. Converting10to public digital holdings uses equal reserve/deposit outflows,other items fixed. Uconverts30without promised extra finance against20reserves. Transition budget6,000:staged pilot2,000,advice/access card2,000,technical testing2,000. Alternative broad rollout6,000without support;actual take-up,costs,risks unknown. Cash remains possible. Extra funding may be available but is not guaranteed.''',
['Für A: Trenne tatsächlichen Beschluss, regionaleModelllage und unsichereWirkung. Entwickle zwei vernetzte Problem-/Wirkungsketten aus Zins, Nachfrage und Energieangebot.','Entwickle/vergleiche zwei finanzierbareAnsätze anhandT/B: rechneBudget,Haushaltsbelastung undOpportunitätskosten; erörtereWachstum undBeschäftigung mitPreis-/Zeitgegeneffekten.','Begründe ein bedingtesGesamturteil mit Finanzierung,Verteilung undUmwelt. Nenne eineRevisionsgröße statt einer garantierten Ein-Hebel-Lösung.','Für B: Berechne die begrenzteBilanzumwandlung10und die anfänglicheU-Finanzierungslücke. Erkläre Zahlungs-/Geldform und den Unterschied zuEigenkapitalverlust oder neuerKreditvergabe.','Entwickle zwei Übergangsansätze aus demBudget. Vernetze Teilhabe,Zahlungskosten, Bankenfinanzierung undStabilität; prüfeInstitutionen/Gesetzgebungs- undAusgabevorbehalt.','Erörtere beideAnsätze mit mindestens zwei Betroffenengruppen,Finanzierung undRessourcen. Begründe ein anpassbaresUrteil mit Modell-/Zeitgrenze; Zahlungsinnovation löst nicht automatisch Energie-/Beschäftigungsprobleme.'],
['For A,separate decision,regional assumptions,uncertain effects; develop two linked rate,demand,supply chains.','Develop/compare two fundedT/Bapproaches:calculate budget,household burden,opportunity cost;discuss growth/jobs with price/time countereffects.','Give a conditional funding,distribution,environment judgment and review signal,not a guaranteed one-lever solution.','For B,calculate conversion10and initialUfunding gap;explain money/payment form versus equity loss/new lending.','Develop two budget-bound transitions linking inclusion,payment costs,bank funding,stability;examine institutional/legislative/issuance conditions.','Discuss both approaches for two affected groups,funding/resources;justify an adaptive judgment with model/time limits,not automatic energy/job solutions.'],
['RealerBeschluss+0,25pp, eigene100Haushalte/Budgetdaten, ungewisseTransmission unterscheiden. Zins→Finanzierung/Kreditnachfrage→Investition/Konsum→Produktion/Jobs/Preise bedingt; Entlastung→Kaufkraft→Nachfrage beiEnergieengpass möglichPreisdruck. Effizienz→späterwenigerEnergiebedarf/Angebotsentlastung benötigtRessourcen, keinZins erzeugtphysischEnergie.','T=5.000+7.000=12.000;B=6.000+6.000=12.000. Energieplus20jeMonat=20% undgesamt2.000monatlich, nichtmitEinmalbudgetzeitlichgleichsetzen. Tzielgenauer, Beffizienz6statt7undbreiterZugang; beideverdrängen12.000Alternative. Nachfragekanal kannAbsatz/Jobsstützen oderPreisebeiKnappheit; höhereZinsen könnenInvestitionbremsen, Arbeits-/Produktivitätsreaktionoffen.','TmitZugangsprüfung/gestuftemEffizienzprojekt istvertretbar, auchbedingtB. Wirkung/Verteilung/UmweltinklusiveDurchführungskosten/Gegeneffekte abwägen. Energieeinsparung, Erreichbarkeit, tatsächlicheAufträge/Preise prüfen; keinegesicherteWachstums- oderBeschäftigungsgröße.','Reserven20→10,Einlagen100→90;Aktiva130=Passiva130, Kredite80/Eigenkapital40gleich. UmwandlungändertVerbindlichkeits-/Finanzierungsstruktur,nichtautomatischBilanzverlust. U30−20=10anfänglicheLiquiditäts-/Finanzierungslücke; Refinanzierung/Zeitreaktionoffen. Keineheutige10-Haltegrenze behaupten.','Pilot+Karte/Beratung+Prüfung=6.000oderbreit6.000ohneHilfe. ErsterAnsatz kannZugang/Risikenprüfen, zweiterReichweitebeschleunigen, abermehrAusschluss/Finanzierungsrisiko. Öffentlichkeit/digitalesZentralbankgeld undprivateBankeinlageunterscheiden; Gesetzgebung/spätereAusgabeentscheidung nochBedingung.','MenschenohneSmartphone profitierenvonKarte/Bargeld/Betreuung, Banken brauchenLiquiditätsplanung, HändlernutzenZahlungsverfahrenmitKosten. Stufenwahlen mitZugangs-/Liquiditäts-/Sicherheitsprüfsignal begründen, alternativeUrteilezählen. Kein2029Garantietermin oder sichererBankverlust;6.000fehltanderenZwecken und löstkeinEnergieangebot.'],
['Separateactual+0.25ppdecision,inventedhousehold/budget data,uncertaintransmission. Rates→funding/credit→investment/spending→output/jobs/prices conditionally;relief→demand may raiseprices under energyshortage. Efficiency may later reduceenergyneed,requiringresources;ratescreate noenergy directly.','T5,000+7,000=12,000;B6,000+6,000=12,000. Energy+20permonth=20%,aggregate2,000monthly,not the sameperiod asone-offbudget. Targeting/access and efficiency7versus6 differ. Bothdisplace12,000alternative;demandmay supportoutput/jobs orprices,ratecostsmay constraininvestment,jobs/productivity uncertain.','TorBcan be defendedconditionally. Weigh access,distribution,environment,deliverycost,countereffects. Monitoractualsavings,orders/prices,not assuredoutput/jobs.','Reserves20→10,deposits100→90,assets130=liabilities130;loans80/equity40unchanged. Conversionchangesfunding,notautomaticloss. Uhasinitialgap30−20=10,withadditionalfunding/response open. No actual10holdinglimit is claimed.','Pilot+advice/card+testing=6,000or broad6,000without support. Pilotmay checkaccess/risk;broadmay scalefaster with exclusion/fundingrisks. Distinguishpubliccentralbankmoney/privatebankdeposits;legislation/laterdecision areconditions.','Peoplewithoutsmartphones may needcards,cash,support;banksneedliquidityplanning;merchantsfacepaymentcosts. Justifyadaptation after access/liquidity/security signals. No guaranteed2029issuance/bankloss;6,000displacesalternatives andcreates noenergy.'],
['2 BE für tatsächlicherBeschluss/Modell/Unsicherheit getrennt; 2 für zwei vernetzte richtigeMechanismen.','2 BE für beideBudgets/Belastung/Zeiteinheit; 2 für eigenständigeWachstums-/Beschäftigungsabwägung undGegeneffekte.','2 BE für Finanzierung/Verteilung/Umwelt; 2 für bedingtesUrteil und tatsächlicheRevisionsgröße.','2 BE für konsistenteBilanz10/U-Lücke; 2 für Geldform/Finanzierung gegenüberVerlust/Kreditvergabe getrennt.','2 BE für zweiBudgetansätze/mehrereKanäle; 2 für institutionelleStatus-/Gesetzgebungsbedingungen.','2 BE für mindestenszweiPerspektiven/Ressourcen/Finanzierung; 2 für bedingtes anpassbaresUrteil undModell-/Zeitgrenze.'],
['2for decision/model/uncertainty separation;2for two connected correct mechanisms.','2for both budgets/burden/timeunit;2for distinct growth/jobs/countereffects.','2for funding/distribution/environment;2for conditional judgment/actual review signal.','2for coherent conversion/Ugap;2for money/funding versusloss/lending.','2for two funded multi-channel approaches;2for institutional/legislative conditions.','2for two perspectives/resources/funding;2for adaptive judgment/model/time limits.'],
'mehrere materialgebundene vernetzte Lösungsansätze; nachvollziehbare Zins-/Nachfrage-/Angebotskanäle; eine eigenständige Finanzierungs-/Verteilungsabwägung; eigenständig behandelte Wachstum/Beschäftigung und Umwelt; Zahlungs-/Bankfinanzierungs-/Stabilitätskanäle des anderen Falls; konkrete institutionelle und kausale Modellgrenzen',
'multiple case-grounded connected approaches; intelligible rate/demand/supply channels; distinct funding/distribution assessment; separately considered growth/jobs and environment; payment/bank-funding/stability channels in the other case; concrete institutional and causal model limits')
p=O/'whole-seven-policy-wage-skills-scenarios-one-contract-DEEN.two-case-DRAFT.author-v1.json';assert not p.exists();p.write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'path':str(p.relative_to(R)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'materials':len(items),'cases':14,'steps':42,'ids':[x['id'] for x in items]}))
